export function applyF360Recovery401(draw:BuildingComponent[],colors:Float32Array,frames:Float32Array,sourceRows:readonly BuildingComponent[],leaf:Leaf401|undefined,patch:Leaf401|undefined){const plan=f360Plan401(sourceRows,leaf,patch);if(!plan.ready||plan.held.some(c=>draw.includes(c))||!plan.derived.every(c=>draw.includes(c)))return{painted:0};let at=0,painted=0;
 for(const c of draw){const fs=FRAMES401.find(f=>f.partId===c.partId);for(const [bi,b]of c.batches.entries())for(let j=0;j<b.positions.length;j+=3,at++){if(!fs)continue;const f=fs.frames.find(f=>f.batchIndex===bi);if(!f)continue;const x=b.positions[j],y=b.positions[j+1],z=b.positions[j+2],u=f.uAxis[0]*x+f.uAxis[1]*y+f.uAxis[2]*z-f.uOrigin,v=f.vAxis[0]*x+f.vAxis[1]*y+f.vAxis[2]*z-f.vOrigin;frames.set([u,v,f.height,f.width,1704],at*5);colors.set([...b.color,2],at*4);painted++;}}
 return{painted,nativeArraysChanged:false};}
